public void execute(Long jobId) {
    MailReportJob job = jobDao.getById(jobId);
    if (job == null || !Integer.valueOf(1).equals(job.getEnabled())) {
        return;
    }
    // 业务日 = 今天减偏移天数，报表默认统计昨天
    LocalDate businessDate = LocalDate.now().minusDays(
            job.getBusinessDateOffsetDays() == null ? 1 : job.getBusinessDateOffsetDays());
    String lockKey = "sendmail:job:" + jobId + ":" + businessDate;
    String token = UUID.randomUUID().toString();
    // 同一个任务同一个业务日只允许一次，重复触发直接放弃
    Boolean locked = redis.opsForValue().setIfAbsent(lockKey, token, LOCK_TTL_30MIN);
    if (!Boolean.TRUE.equals(locked)) {
        log.info("job already running or done, jobId: {}, date: {}", jobId, businessDate);
        return;
    }
    try {
        updateStatus(jobId, businessDate, STATUS_PROCESSING);
        doExecute(job, businessDate);
        updateStatus(jobId, businessDate, STATUS_SUCCESS);
    } catch (Exception e) {
        log.error("mail job failed, jobId: {}", jobId, e);
        updateStatus(jobId, businessDate, STATUS_FAILED);
    } finally {
        releaseLock(lockKey, token);       // 校验 token 再删，防止误删别人的锁
    }
}

@Transactional(rollbackFor = Exception.class)
public void update(Long id, MailJobBo bo) {
    MailReportJob exist = jobDao.getById(id);
    if (exist == null) {
        throw new BizException("任务不存在");
    }
    // 改名查重必须排除自己，否则改成同名等于必然冲突
    if (!Objects.equals(exist.getJobName(), bo.getJobName())
            && jobDao.existsByJobName(bo.getJobName(), id)) {
        throw new BizException("任务名已存在: " + bo.getJobName());
    }
    exist.setJobName(bo.getJobName());
    exist.setCron(bo.getCron());
    exist.setReportSql(bo.getReportSql());
    // 不改运行状态：改配置不应该顺手把启用/停用也重置了
    jobDao.updateById(exist);
    // 收件人整表替换：先删再批量插
    recipientDao.deleteByJobId(id);
    insertRecipients(id, bo.getRecipients());
}
